:root {
  --ink: #0b1322;
  --ink-2: #111d31;
  --ink-3: #182941;
  --cream: #f7f1df;
  --muted: #9fb0c7;
  --line: rgba(255, 255, 255, 0.13);
  --blue: #45b6ff;
  --blue-deep: #1b7fd4;
  --red: #ff5d6c;
  --red-deep: #d23a52;
  --yellow: #ffd447;
  --yellow-deep: #d99c12;
  --green: #64d98b;
  --wood: #c98a4b;
  --wood-deep: #8e5a2c;
  --brick: #d9755f;
  --brick-deep: #a04335;
  --metal: #a9bed2;
  --metal-deep: #647d95;
  --radius: 16px;
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
  --font-display: "Bungee", "Arial Black", "Trebuchet MS", sans-serif;
  --font-ui: "Nunito", "Trebuchet MS", system-ui, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0c1424;
  color: var(--cream);
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  overscroll-behavior: none;
}

button {
  font-family: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  isolation: isolate;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

.is-hidden { display: none !important; }

.noise {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.055;
  z-index: 90;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}

/* ============================================================
   HUD
   ============================================================ */
.hud {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: max(14px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right)) max(14px, env(safe-area-inset-bottom)) max(16px, env(safe-area-inset-left));
}

.topbar {
  display: grid;
  grid-template-columns: minmax(220px, 300px) minmax(220px, 1fr) minmax(220px, 300px);
  gap: 18px;
  align-items: start;
  width: 100%;
}

.team-panel {
  pointer-events: auto;
  background: linear-gradient(180deg, rgba(15, 25, 42, 0.93), rgba(10, 18, 31, 0.82));
  border: 1.5px solid var(--line);
  border-radius: 14px;
  padding: 9px 11px 10px;
  box-shadow: 0 8px 26px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
}

.team-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 7px;
  font-family: var(--font-display);
  font-size: 12px;
  letter-spacing: 0.06em;
}
.team-red .team-head { justify-content: flex-end; }
.team-dot {
  width: 9px; height: 9px; border-radius: 50%;
  background: var(--blue);
  box-shadow: 0 0 10px var(--blue);
}
.team-red .team-dot { background: var(--red); box-shadow: 0 0 10px var(--red); }
.team-name { color: var(--cream); }
.team-tag {
  margin-left: auto;
  font-family: var(--font-ui);
  font-weight: 900;
  font-size: 9px;
  letter-spacing: 0.12em;
  color: var(--ink);
  background: var(--yellow);
  padding: 2px 6px;
  border-radius: 4px;
}
.team-red .team-tag { margin-left: 0; margin-right: auto; background: rgba(255, 93, 108, 0.2); color: #ffb3ba; }

.worm-list { display: flex; flex-direction: column; gap: 5px; }
.team-red .worm-row { flex-direction: row-reverse; }
.team-red .worm-row .w-info { align-items: flex-end; }
.team-red .w-bar i { margin-left: auto; }

.worm-row {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 3px 4px;
  border-radius: 8px;
  transition: background 0.2s ease, opacity 0.2s ease;
}
.worm-row.active { background: rgba(69, 182, 255, 0.14); box-shadow: inset 0 0 0 1px rgba(69, 182, 255, 0.35); }
.team-red .worm-row.active { background: rgba(255, 93, 108, 0.14); box-shadow: inset 0 0 0 1px rgba(255, 93, 108, 0.35); }
.worm-row.dead { opacity: 0.38; filter: grayscale(1); }
.worm-row.dead .w-name { text-decoration: line-through; }

.w-face {
  width: 22px; height: 22px;
  flex: 0 0 22px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #ffd1dc, #f08ca5 60%, #b94a67);
  border: 2px solid rgba(255, 255, 255, 0.65);
  position: relative;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.35);
}
.w-face::before, .w-face::after {
  content: ""; position: absolute; top: 7px; width: 3px; height: 4px; border-radius: 50%; background: #2a1220;
}
.w-face::before { left: 5px; } .w-face::after { right: 5px; }
.team-blue .w-face { background: radial-gradient(circle at 35% 30%, #d9f2ff, #7cc9f2 55%, #3b86b3); }
.w-face i {
  position: absolute; left: -2px; right: -2px; top: -4px; height: 8px;
  border-radius: 8px 8px 3px 3px;
  background: var(--blue-deep);
  border: 1px solid rgba(255, 255, 255, 0.4);
}
.team-red .w-face i { background: var(--red-deep); }

.w-info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.w-name {
  font-weight: 900;
  font-size: 11px;
  letter-spacing: 0.03em;
  color: #e9f1fb;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.w-bar {
  height: 5px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.1);
  overflow: hidden;
}
.w-bar i {
  display: block;
  height: 100%;
  width: 100%;
  border-radius: 3px;
  background: linear-gradient(90deg, #67e38e, #37b96a);
  transition: width 0.35s ease;
}
.w-bar i.low { background: linear-gradient(90deg, #ffd447, #ff9d2e); }
.w-bar i.crit { background: linear-gradient(90deg, #ff6b7b, #e02c48); }
.w-hp {
  font-family: var(--font-display);
  font-size: 9px;
  color: var(--muted);
  min-width: 22px;
  text-align: right;
}

/* ---- center turn / wind ---- */
.turn-box {
  justify-self: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  pointer-events: none;
  padding-top: 2px;
}
.wind-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 11px;
  background: rgba(11, 19, 34, 0.8);
  border: 1.5px solid var(--line);
  border-radius: 999px;
  backdrop-filter: blur(8px);
}
.wind-label {
  font-family: var(--font-display);
  font-size: 9px;
  letter-spacing: 0.12em;
  color: var(--muted);
}
.wind-gauge {
  position: relative;
  width: 74px;
  height: 6px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.11);
  overflow: hidden;
}
.wind-gauge i {
  position: absolute;
  top: 0; bottom: 0; left: 50%;
  width: 0%;
  background: linear-gradient(90deg, #5fd6ff, #ffd447);
  border-radius: 4px;
  transition: width 0.4s ease, left 0.4s ease;
}
.wind-center {
  position: absolute;
  left: 50%; top: -2px; bottom: -2px;
  width: 2px;
  margin-left: -1px;
  background: rgba(255, 255, 255, 0.55);
}
.wind-value {
  font-family: var(--font-display);
  font-size: 10px;
  color: var(--yellow);
  min-width: 42px;
  text-align: right;
  letter-spacing: 0.02em;
}
.turn-label {
  font-family: var(--font-display);
  font-size: 11px;
  letter-spacing: 0.1em;
  color: #dfe9f7;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.65);
}
.turn-label.blue { color: #8fd8ff; }
.turn-label.red { color: #ffa5ad; }

/* ---- toast ---- */
.toast {
  position: absolute;
  top: 118px;
  left: 50%;
  transform: translate(-50%, -12px);
  padding: 9px 20px;
  border-radius: 10px;
  background: rgba(9, 16, 28, 0.92);
  border: 1.5px solid rgba(255, 212, 71, 0.55);
  color: var(--cream);
  font-family: var(--font-display);
  font-size: 13px;
  letter-spacing: 0.07em;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s ease, transform 0.22s ease;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
  white-space: nowrap;
  z-index: 35;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast.warn { border-color: rgba(255, 93, 108, 0.7); color: #ffd9dd; }

/* ---- build banner ---- */
.build-banner {
  position: absolute;
  top: 108px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px;
  border-radius: 10px;
  background: rgba(9, 16, 28, 0.9);
  border: 1.5px solid rgba(100, 217, 139, 0.65);
  box-shadow: 0 0 24px rgba(100, 217, 139, 0.15);
  font-family: var(--font-display);
  font-size: 11px;
  letter-spacing: 0.07em;
  color: #b9f5cd;
  z-index: 32;
  white-space: nowrap;
}
.build-banner span:not(.build-pulse):not(.build-piece) {
  font-family: var(--font-ui);
  font-weight: 800;
  color: #86a58f;
  font-size: 10px;
  letter-spacing: 0.04em;
}
.build-pulse {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 10px var(--green);
  animation: pulse 1.2s infinite;
}
.build-piece {
  padding: 2px 7px;
  border-radius: 5px;
  background: var(--green);
  color: #0a2014;
  font-size: 10px;
}

/* ---- reaction ---- */
.reaction {
  position: absolute;
  left: 50%;
  bottom: 132px;
  transform: translateX(-50%);
  z-index: 40;
  pointer-events: auto;
}
.reaction-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px 10px 16px;
  border-radius: 14px;
  background: linear-gradient(180deg, rgba(46, 12, 18, 0.95), rgba(25, 8, 13, 0.95));
  border: 2px solid rgba(255, 93, 108, 0.8);
  box-shadow: 0 0 0 4px rgba(255, 93, 108, 0.12), 0 16px 40px rgba(0, 0, 0, 0.5), 0 0 40px rgba(255, 93, 108, 0.25);
  animation: reactionPulse 0.9s ease-in-out infinite alternate;
}
.reaction-warn {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-display);
  font-size: 12px;
  letter-spacing: 0.08em;
  color: #ff8b96;
}
.reaction-warn span { font-size: 18px; }
.reaction-btn {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1px;
  padding: 8px 16px;
  border-radius: 9px;
  background: linear-gradient(180deg, #ff6b78, #d92f48);
  border-bottom: 3px solid #8f1327;
  box-shadow: 0 4px 0 rgba(0, 0, 0, 0.2);
  transition: transform 0.08s ease, filter 0.15s ease;
}
.reaction-btn:hover { filter: brightness(1.08); }
.reaction-btn:active { transform: translateY(2px); }
.reaction-main {
  font-family: var(--font-display);
  font-size: 13px;
  letter-spacing: 0.06em;
  color: #fff;
}
.reaction-cost {
  font-weight: 900;
  font-size: 10px;
  letter-spacing: 0.08em;
  color: #ffd9dd;
}
.reaction-key {
  font-family: var(--font-display);
  font-size: 9px;
  letter-spacing: 0.06em;
  color: rgba(255, 255, 255, 0.5);
  padding: 4px 7px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 5px;
}

/* ---- hintbar ---- */
.hintbar {
  position: absolute;
  left: 50%;
  bottom: 108px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 7px;
  font-weight: 800;
  font-size: 11px;
  color: rgba(238, 246, 255, 0.62);
  text-shadow: 0 2px 6px rgba(0, 0, 0, 0.8);
  pointer-events: none;
  white-space: nowrap;
  z-index: 24;
}
.hint-ico { font-size: 13px; opacity: 0.8; }

/* ---- bottom bar ---- */
.bottombar {
  display: grid;
  grid-template-columns: 250px minmax(0, 1fr) auto;
  gap: 14px;
  align-items: end;
  width: 100%;
  pointer-events: none;
}
.bottombar > * { pointer-events: auto; }

.worm-card {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 12px;
  border-radius: 15px;
  background: linear-gradient(180deg, rgba(15, 25, 42, 0.94), rgba(9, 16, 28, 0.9));
  border: 1.5px solid var(--line);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(9px);
}
.worm-avatar {
  position: relative;
  width: 46px; height: 46px;
  flex: 0 0 46px;
  border-radius: 13px;
  background: radial-gradient(circle at 38% 28%, #d9f2ff, #6fc3ef 48%, #2a6f9d);
  border: 2px solid rgba(255, 255, 255, 0.55);
  box-shadow: inset 0 -8px 16px rgba(0, 0, 0, 0.28), 0 3px 10px rgba(0, 0, 0, 0.35);
  overflow: hidden;
}
.worm-avatar::before, .worm-avatar::after {
  content: ""; position: absolute; top: 18px; width: 5px; height: 7px; border-radius: 50%; background: #102030;
  z-index: 2;
}
.worm-avatar::before { left: 13px; } .worm-avatar::after { right: 13px; }
.worm-avatar span {
  position: absolute; left: 6px; right: 6px; top: 4px; height: 15px;
  border-radius: 10px 10px 4px 4px;
  background: linear-gradient(180deg, #2e93d8, #17669e);
  border-bottom: 2px solid rgba(0, 0, 0, 0.2);
  z-index: 3;
}
.worm-avatar.red { background: radial-gradient(circle at 38% 28%, #ffd9de, #f28aa0 48%, #a33a54); }
.worm-avatar.red span { background: linear-gradient(180deg, #ff6b7b, #c72d47); }
.worm-meta { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.worm-name-row { display: flex; align-items: center; gap: 6px; }
.worm-name {
  font-family: var(--font-display);
  font-size: 13px;
  letter-spacing: 0.04em;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.worm-team {
  font-weight: 900;
  font-size: 8px;
  letter-spacing: 0.1em;
  padding: 2px 5px;
  border-radius: 4px;
  background: rgba(69, 182, 255, 0.18);
  color: #9fdcff;
}
.worm-team.red { background: rgba(255, 93, 108, 0.18); color: #ffb1b9; }

.meter {
  position: relative;
  height: 13px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.09);
  overflow: hidden;
}
.meter i {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  border-radius: 6px;
  transition: width 0.35s ease;
}
.meter span {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 8px;
  letter-spacing: 0.06em;
  color: #06101b;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.22);
}
.hp-meter i { background: linear-gradient(180deg, #75ea9a, #35b968); }
.hp-meter i.low { background: linear-gradient(180deg, #ffd966, #eaa21f); }
.hp-meter i.crit { background: linear-gradient(180deg, #ff7c88, #d92f48); }
.move-meter { height: 9px; }
.move-meter i { background: linear-gradient(180deg, #8fd8ff, #3a9dd6); }
.move-meter span { font-size: 7px; color: #dff3ff; text-shadow: 0 1px 2px rgba(0, 0, 0, 0.5); }

/* ---- action dock ---- */
.action-dock {
  display: flex;
  align-items: stretch;
  justify-content: center;
  gap: 9px;
  padding: 8px 10px;
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(15, 25, 42, 0.94), rgba(9, 16, 28, 0.92));
  border: 1.5px solid var(--line);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(9px);
  width: 100%;
  max-width: 660px;
  justify-self: center;
  overflow: hidden;
}
.dock-group { display: flex; align-items: stretch; gap: 6px; }
.dock-divider { width: 1px; align-self: stretch; background: rgba(255, 255, 255, 0.1); margin: 2px 1px; }

.dock-btn {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-width: 58px;
  padding: 6px 9px 7px;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.055);
  border: 1.5px solid rgba(255, 255, 255, 0.08);
  border-bottom: 3px solid rgba(0, 0, 0, 0.35);
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.08s ease;
  overflow: hidden;
}
.dock-btn:hover { background: rgba(255, 255, 255, 0.1); }
.dock-btn:active { transform: translateY(1px); }
.dock-btn.active {
  background: linear-gradient(180deg, rgba(255, 212, 71, 0.22), rgba(255, 212, 71, 0.09));
  border-color: rgba(255, 212, 71, 0.75);
  box-shadow: 0 0 14px rgba(255, 212, 71, 0.16);
}
.dock-btn .key {
  position: absolute;
  top: 3px; right: 4px;
  font-family: var(--font-display);
  font-size: 7px;
  color: rgba(255, 255, 255, 0.4);
}
.dock-btn .lbl {
  font-family: var(--font-display);
  font-size: 9px;
  letter-spacing: 0.04em;
  color: #e8f2ff;
}
.dock-btn .sub {
  font-weight: 900;
  font-size: 8px;
  letter-spacing: 0.03em;
  color: var(--muted);
}
.dock-btn.active .sub { color: #ffe9a3; }
.dock-btn .swatch {
  width: 16px; height: 5px;
  border-radius: 2px;
  margin-bottom: 1px;
}
.swatch.wood { background: var(--wood); }
.swatch.brick { background: var(--brick); }
.swatch.metal { background: var(--metal); }
.dock-btn .piece-ico {
  width: 18px; height: 13px;
  display: block;
  margin-bottom: 1px;
  opacity: 0.9;
}
.dock-btn.disabled { opacity: 0.38; filter: grayscale(0.6); }
.dock-btn.disabled:hover { background: rgba(255, 255, 255, 0.055); }

/* ---- utility ---- */
.utility { display: flex; align-items: stretch; gap: 7px; }
.util-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-width: 44px;
  height: 100%;
  min-height: 50px;
  padding: 0 11px;
  border-radius: 12px;
  background: rgba(12, 20, 35, 0.9);
  border: 1.5px solid var(--line);
  border-bottom: 3px solid rgba(0, 0, 0, 0.4);
  font-family: var(--font-display);
  font-size: 10px;
  letter-spacing: 0.05em;
  color: #dfe9f7;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.08s ease;
}
.util-btn:hover { background: rgba(255, 255, 255, 0.1); }
.util-btn:active { transform: translateY(1px); }
.util-btn .key {
  font-size: 8px;
  padding: 2px 4px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.12);
  color: #b9c8da;
}
.build-toggle.active {
  background: linear-gradient(180deg, rgba(100, 217, 139, 0.28), rgba(100, 217, 139, 0.1));
  border-color: rgba(100, 217, 139, 0.8);
  color: #b9f5cd;
}
.icon-btn { font-size: 15px; min-width: 42px; padding: 0 8px; }

/* ---- touch move ---- */
.touch-move {
  display: none;
  position: absolute;
  left: max(12px, env(safe-area-inset-left));
  bottom: calc(96px + env(safe-area-inset-bottom));
  gap: 7px;
  pointer-events: auto;
  z-index: 30;
}
.touch-btn {
  width: 54px; height: 54px;
  border-radius: 14px;
  background: rgba(12, 20, 35, 0.9);
  border: 1.5px solid rgba(255, 255, 255, 0.2);
  border-bottom: 3px solid rgba(0, 0, 0, 0.45);
  color: #eaf3ff;
  font-family: var(--font-display);
  font-size: 18px;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.4);
  touch-action: none;
}
.touch-btn.jump { font-size: 9px; width: 58px; background: rgba(69, 182, 255, 0.2); border-color: rgba(69, 182, 255, 0.5); }
.touch-btn:active { transform: translateY(2px); background: rgba(255, 255, 255, 0.16); }

/* ============================================================
   OVERLAYS
   ============================================================ */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.menu-overlay {
  background:
    radial-gradient(ellipse at 50% 42%, rgba(11, 19, 34, 0.15), rgba(7, 12, 22, 0.82) 72%),
    linear-gradient(180deg, rgba(8, 14, 25, 0.55), rgba(6, 10, 18, 0.9));
  overflow: hidden;
}
.menu-overlay::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 45%, transparent 20%, rgba(5, 9, 16, 0.55) 100%);
  pointer-events: none;
}

.menu-card {
  position: relative;
  z-index: 2;
  width: min(760px, 100%);
  text-align: center;
  padding: 12px;
  animation: riseIn 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.eyebrow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-family: var(--font-display);
  font-size: 9px;
  letter-spacing: 0.28em;
  color: #91b7d8;
  text-transform: uppercase;
  margin-bottom: 12px;
}
.eyebrow span { width: 34px; height: 1px; background: linear-gradient(90deg, transparent, #6d94b8); }
.eyebrow span:last-child { background: linear-gradient(90deg, #6d94b8, transparent); }

.logo {
  margin: 0;
  font-family: var(--font-display);
  line-height: 0.82;
  letter-spacing: 0.015em;
  display: flex;
  flex-direction: column;
  align-items: center;
  filter: drop-shadow(0 10px 0 rgba(0, 0, 0, 0.22)) drop-shadow(0 22px 44px rgba(0, 0, 0, 0.5));
}
.logo-top {
  font-size: clamp(44px, 9vw, 94px);
  color: #f7f1df;
  -webkit-text-stroke: 2px #0b1322;
  text-shadow: 0 5px 0 #233a55, 0 10px 0 #0b1322;
}
.logo-bottom {
  font-size: clamp(52px, 11vw, 116px);
  color: var(--yellow);
  -webkit-text-stroke: 2px #0b1322;
  text-shadow: 0 6px 0 #b36f10, 0 12px 0 #0b1322, 0 20px 40px rgba(0, 0, 0, 0.55);
  transform: rotate(-1.5deg);
}
.tagline {
  margin: 20px 0 26px;
  font-weight: 800;
  font-size: clamp(12px, 1.7vw, 15px);
  letter-spacing: 0.03em;
  color: #c7d9ec;
  line-height: 1.55;
}
.tagline em { color: #8fd8ff; font-style: normal; }

.mode-row {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}
.big-btn {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
  min-width: 218px;
  padding: 13px 22px 14px;
  border-radius: 12px;
  border-bottom: 4px solid rgba(0, 0, 0, 0.4);
  transition: transform 0.12s ease, filter 0.15s ease;
  text-align: left;
}
.big-btn:hover { transform: translateY(-2px); filter: brightness(1.07); }
.big-btn:active { transform: translateY(1px); }
.big-btn.primary {
  background: linear-gradient(180deg, #ffe066, #f5b820);
  color: #1b1405;
  border-bottom-color: #a86d06;
  box-shadow: 0 10px 30px rgba(245, 184, 32, 0.22);
}
.big-btn.ghost {
  background: linear-gradient(180deg, rgba(28, 44, 67, 0.95), rgba(18, 30, 48, 0.95));
  color: #eaf3ff;
  border: 1.5px solid rgba(255, 255, 255, 0.16);
  border-bottom: 4px solid rgba(0, 0, 0, 0.45);
}
.big-btn-main { font-family: var(--font-display); font-size: 16px; letter-spacing: 0.04em; }
.big-btn-sub { font-weight: 800; font-size: 10px; letter-spacing: 0.04em; opacity: 0.62; }
.big-btn.wide { width: 100%; align-items: center; margin-top: 20px; }

.difficulty {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 16px;
  font-family: var(--font-display);
  font-size: 9px;
  letter-spacing: 0.1em;
}
.diff-label { color: #7996b4; margin-right: 3px; }
.difficulty button {
  padding: 5px 11px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(10, 18, 30, 0.6);
  color: #9fb0c7;
  font-family: var(--font-display);
  font-size: 9px;
  letter-spacing: 0.08em;
  transition: all 0.15s ease;
}
.difficulty button:hover { color: #fff; border-color: rgba(255, 255, 255, 0.35); }
.difficulty button.active {
  background: rgba(69, 182, 255, 0.2);
  border-color: rgba(69, 182, 255, 0.75);
  color: #bfeaff;
}

.menu-foot {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  margin-top: 22px;
  flex-wrap: wrap;
}
.text-btn {
  font-family: var(--font-display);
  font-size: 10px;
  letter-spacing: 0.08em;
  color: #cfe2f5;
  padding: 7px 12px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(10, 18, 30, 0.55);
  transition: all 0.15s ease;
}
.text-btn:hover { border-color: var(--yellow); color: var(--yellow); }
.menu-controls {
  font-weight: 800;
  font-size: 9px;
  letter-spacing: 0.08em;
  color: #6f8aa5;
}
.menu-credit {
  position: absolute;
  bottom: max(16px, env(safe-area-inset-bottom));
  left: 0; right: 0;
  text-align: center;
  font-weight: 800;
  font-size: 9px;
  letter-spacing: 0.1em;
  color: rgba(160, 184, 208, 0.45);
  z-index: 2;
}

/* floating decorative tiles */
.float-tiles { position: absolute; inset: 0; pointer-events: none; overflow: hidden; z-index: 1; }
.tile {
  position: absolute;
  width: 46px; height: 46px;
  border-radius: 8px;
  background: linear-gradient(145deg, rgba(201, 138, 75, 0.55), rgba(110, 67, 32, 0.45));
  border: 2px solid rgba(255, 255, 255, 0.12);
  box-shadow: inset 0 0 0 2px rgba(0, 0, 0, 0.18), 0 14px 30px rgba(0, 0, 0, 0.35);
  opacity: 0.5;
  animation: floaty 9s ease-in-out infinite;
}
.tile::before, .tile::after {
  content: ""; position: absolute; inset: 7px;
  border: 2px solid rgba(255, 255, 255, 0.13);
  border-radius: 3px;
}
.tile::after { inset: 14px; border-color: rgba(0, 0, 0, 0.18); }
.t1 { left: 7%; top: 20%; transform: rotate(-14deg); animation-delay: -1s; }
.t2 { right: 9%; top: 16%; transform: rotate(11deg); background: linear-gradient(145deg, rgba(217, 117, 95, 0.5), rgba(130, 55, 45, 0.4)); animation-delay: -4s; }
.t3 { left: 12%; bottom: 15%; transform: rotate(8deg); width: 34px; height: 34px; background: linear-gradient(145deg, rgba(169, 190, 210, 0.45), rgba(80, 100, 120, 0.4)); animation-delay: -6s; }
.t4 { right: 13%; bottom: 19%; transform: rotate(-8deg); width: 38px; height: 38px; animation-delay: -2.5s; }

/* ============================================================
   SHEETS (help / game over)
   ============================================================ */
.sheet-overlay {
  background: rgba(6, 11, 20, 0.74);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.sheet {
  position: relative;
  width: min(720px, 100%);
  max-height: calc(100dvh - 48px);
  overflow-y: auto;
  padding: 28px 32px 30px;
  border-radius: 20px;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(69, 182, 255, 0.09), transparent 55%),
    linear-gradient(180deg, #16243a, #0c1626 65%);
  border: 1.5px solid rgba(255, 255, 255, 0.15);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  animation: riseIn 0.4s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.2) transparent;
}
.sheet-close {
  position: absolute;
  top: 14px; right: 14px;
  width: 32px; height: 32px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #b9c8da;
  font-size: 13px;
  transition: all 0.15s ease;
}
.sheet-close:hover { background: rgba(255, 93, 108, 0.2); color: #fff; }
.sheet-title {
  margin: 0 0 20px;
  font-family: var(--font-display);
  font-size: clamp(22px, 4vw, 34px);
  letter-spacing: 0.02em;
  text-align: center;
  color: var(--cream);
  text-shadow: 0 4px 0 rgba(0, 0, 0, 0.3);
}
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.help-col h3 {
  margin: 0 0 9px;
  font-family: var(--font-display);
  font-size: 11px;
  letter-spacing: 0.1em;
  color: var(--yellow);
}
.help-col ul { margin: 0; padding-left: 17px; display: flex; flex-direction: column; gap: 7px; }
.help-col li { font-size: 12px; font-weight: 700; line-height: 1.5; color: #c4d5e7; }
.help-col li b { color: #fff; font-weight: 900; }
.help-tip {
  margin-top: 20px;
  padding: 12px 14px;
  border-radius: 10px;
  background: rgba(255, 212, 71, 0.07);
  border: 1px solid rgba(255, 212, 71, 0.25);
  font-size: 11.5px;
  font-weight: 700;
  line-height: 1.5;
  color: #e9dcb0;
}
.tip-badge {
  display: inline-block;
  margin-right: 7px;
  padding: 2px 6px;
  border-radius: 4px;
  background: var(--yellow);
  color: #241a03;
  font-family: var(--font-display);
  font-size: 8px;
  letter-spacing: 0.08em;
}

.gameover-sheet { text-align: center; width: min(620px, 100%); }
.winner-burst {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 5px;
  background: var(--yellow);
  color: #241a03;
  font-family: var(--font-display);
  font-size: 10px;
  letter-spacing: 0.16em;
  transform: rotate(-3deg);
  box-shadow: 0 4px 0 rgba(0, 0, 0, 0.25);
}
.winner-title {
  margin: 14px 0 6px;
  font-family: var(--font-display);
  font-size: clamp(26px, 5vw, 44px);
  letter-spacing: 0.02em;
  color: #fff;
  text-shadow: 0 5px 0 rgba(0, 0, 0, 0.28);
}
.winner-title.blue { color: #8fd8ff; }
.winner-title.red { color: #ffa5ad; }
.winner-sub { margin: 0 0 20px; font-weight: 800; font-size: 12px; color: #9fb0c7; }
.stats {
  display: flex;
  justify-content: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 8px;
}
.stat {
  min-width: 108px;
  padding: 10px 12px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.055);
  border: 1px solid rgba(255, 255, 255, 0.09);
}
.stat b { display: block; font-family: var(--font-display); font-size: 18px; color: var(--yellow); }
.stat span { font-weight: 800; font-size: 8.5px; letter-spacing: 0.1em; color: #8ea4bc; }

.rotate-hint {
  position: absolute;
  left: 50%;
  bottom: calc(12px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  z-index: 50;
  padding: 5px 11px;
  border-radius: 999px;
  background: rgba(9, 16, 28, 0.82);
  border: 1px solid rgba(255, 255, 255, 0.14);
  font-weight: 800;
  font-size: 9px;
  letter-spacing: 0.05em;
  color: #9fb0c7;
  white-space: nowrap;
}

/* ============================================================
   ANIMATIONS
   ============================================================ */
@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.55; transform: scale(0.8); }
}
@keyframes reactionPulse {
  from { box-shadow: 0 0 0 4px rgba(255, 93, 108, 0.1), 0 16px 40px rgba(0, 0, 0, 0.5), 0 0 24px rgba(255, 93, 108, 0.18); }
  to { box-shadow: 0 0 0 7px rgba(255, 93, 108, 0.04), 0 16px 40px rgba(0, 0, 0, 0.5), 0 0 46px rgba(255, 93, 108, 0.34); }
}
@keyframes floaty {
  0%, 100% { translate: 0 0; }
  50% { translate: 0 -16px; }
}
@keyframes riseIn {
  from { opacity: 0; transform: translateY(16px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1050px) {
  .topbar { grid-template-columns: minmax(170px, 240px) minmax(160px, 1fr) minmax(170px, 240px); gap: 10px; }
  .bottombar { grid-template-columns: 205px minmax(0, 1fr) auto; gap: 9px; }
  .action-dock { gap: 6px; padding: 7px 8px; }
  .dock-btn { min-width: 50px; padding: 5px 7px 6px; }
  .worm-card { padding: 8px 10px; gap: 8px; }
  .worm-avatar { width: 38px; height: 38px; flex-basis: 38px; border-radius: 10px; }
  .worm-avatar::before, .worm-avatar::after { top: 15px; }
  .worm-avatar::before { left: 10px; } .worm-avatar::after { right: 10px; }
  .worm-avatar span { top: 3px; height: 13px; }
}

@media (max-width: 820px) {
  .hud { padding: max(8px, env(safe-area-inset-top)) max(8px, env(safe-area-inset-right)) max(8px, env(safe-area-inset-bottom)) max(8px, env(safe-area-inset-left)); }
  .topbar { grid-template-columns: 1fr 1fr; gap: 7px; }
  .turn-box { grid-column: 1 / -1; grid-row: 2; flex-direction: row; justify-content: center; gap: 10px; padding-top: 0; }
  .wind-wrap { padding: 3px 9px; }
  .turn-label { font-size: 9px; }
  .team-panel { padding: 6px 8px 7px; border-radius: 11px; }
  .team-head { font-size: 9px; margin-bottom: 4px; }
  .worm-row { gap: 5px; padding: 2px 2px; }
  .w-face { width: 17px; height: 17px; flex-basis: 17px; }
  .w-face::before, .w-face::after { top: 5px; width: 2px; height: 3px; }
  .w-face::before { left: 4px; } .w-face::after { right: 4px; }
  .w-name { font-size: 9px; }
  .w-hp { font-size: 8px; min-width: 18px; }
  .toast { top: 132px; font-size: 11px; padding: 7px 14px; }
  .build-banner { top: 126px; font-size: 9px; padding: 6px 10px; gap: 7px; }
  .build-banner span:not(.build-pulse):not(.build-piece) { display: none; }

  .bottombar { grid-template-columns: 1fr auto; grid-template-rows: auto auto; gap: 6px; }
  .worm-card { grid-column: 1; grid-row: 2; max-width: 190px; }
  .action-dock { grid-column: 1 / -1; grid-row: 1; max-width: none; padding: 6px; gap: 5px; overflow-x: auto; justify-content: flex-start; }
  .utility { grid-column: 2; grid-row: 2; }
  .utility .build-toggle { display: none; }
  .util-btn { min-height: 42px; min-width: 38px; padding: 0 8px; font-size: 9px; }
  .icon-btn { font-size: 13px; }
  .dock-divider { display: none; }
  .dock-btn { min-width: 44px; padding: 4px 6px 5px; }
  .dock-btn .lbl { font-size: 8px; }
  .dock-btn .sub { font-size: 7px; }
  .dock-btn .key { display: none; }
  .dock-btn .swatch { width: 13px; height: 4px; }
  .dock-btn .piece-ico { width: 15px; height: 11px; }
  .worm-name { font-size: 11px; }
  .meter span { font-size: 7px; }
  .hintbar { display: none; }
  .reaction { bottom: 178px; }
  .reaction-card { padding: 8px 9px 8px 12px; gap: 8px; }
  .reaction-warn { font-size: 9px; }
  .reaction-warn span { font-size: 14px; }
  .reaction-main { font-size: 10px; }
  .reaction-key { display: none; }

