const STORE_KEY = "trench-royale-muted";

export class Sfx {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noiseBuf = null;
    this.muted = localStorage.getItem(STORE_KEY) === "1";
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === "suspended") this.ctx.resume().catch(() => {});
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.5;
    this.master.connect(this.ctx.destination);

    const len = Math.floor(this.ctx.sampleRate * 1.2);
    this.noiseBuf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = this.noiseBuf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
  }

  resume() {
    this.init();
    if (this.ctx && this.ctx.state === "suspended") this.ctx.resume().catch(() => {});
  }

  setMuted(m) {
    this.muted = m;
    localStorage.setItem(STORE_KEY, m ? "1" : "0");
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.setTargetAtTime(m ? 0 : 0.5, this.ctx.currentTime, 0.02);
    }
  }

  tone({ freq = 440, endFreq = null, dur = 0.2, type = "sine", gain = 0.2, delay = 0, attack = 0.006 }) {
    if (!this.ctx || this.muted) return;
    const t0 = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (endFreq != null) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.001, gain), t0 + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g).connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.02);
  }

  noise({ dur = 0.3, gain = 0.2, filter = 900, q = 0.7, type = "lowpass", delay = 0, sweepTo = null }) {
    if (!this.ctx || this.muted || !this.noiseBuf) return;
    const t0 = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(filter, t0);
    if (sweepTo != null) f.frequency.exponentialRampToValueAtTime(Math.max(40, sweepTo), t0 + dur);
    f.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(Math.max(0.001, gain), t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(f).connect(g).connect(this.master);
    src.start(t0);
    src.stop(t0 + dur + 0.02);
  }

  click() {
    this.tone({ freq: 620, endFreq: 780, dur: 0.055, type: "triangle", gain: 0.08 });
  }

  select() {
    this.tone({ freq: 460, endFreq: 620, dur: 0.08, type: "triangle", gain: 0.09 });
  }

  error() {
    this.tone({ freq: 190, endFreq: 120, dur: 0.16, type: "square", gain: 0.06 });
  }

  shoot(weapon = "bazooka") {
    this.resume();
    if (weapon === "grenade") {
      this.noise({ dur: 0.18, gain: 0.16, filter: 1800, sweepTo: 500 });
      this.tone({ freq: 260, endFreq: 120, dur: 0.18, type: "triangle", gain: 0.14 });
    } else {
      this.noise({ dur: 0.28, gain: 0.24, filter: 2600, sweepTo: 300 });
      this.tone({ freq: 320, endFreq: 70, dur: 0.26, type: "sawtooth", gain: 0.15 });
      this.tone({ freq: 110, endFreq: 45, dur: 0.32, type: "sine", gain: 0.2 });
    }
  }

  explosion(weapon = "bazooka") {
    this.resume();
    const big = weapon === "grenade" ? 1.25 : 1;
    this.noise({ dur: 0.55 * big, gain: 0.34, filter: 1100, sweepTo: 70 });
    this.tone({ freq: 120, endFreq: 32, dur: 0.5 * big, type: "sine", gain: 0.34 });
    this.tone({ freq: 70, endFreq: 24, dur: 0.65 * big, type: "triangle", gain: 0.2, delay: 0.02 });
    this.noise({ dur: 0.2, gain: 0.12, filter: 3400, type: "highpass", delay: 0.02 });
  }

  build(mat = "wood") {
    this.resume();
    const base = mat === "metal" ? 240 : mat === "brick" ? 160 : 120;
    this.noise({ dur: 0.09, gain: 0.13, filter: mat === "metal" ? 3200 : 1200, type: mat === "metal" ? "highpass" : "bandpass", q: 1.4 });
    this.tone({ freq: base * 2.2, endFreq: base, dur: 0.11, type: "triangle", gain: 0.14 });
    if (mat === "metal") this.tone({ freq: 920, endFreq: 700, dur: 0.16, type: "sine", gain: 0.07, delay: 0.02 });
  }

  jump() {
    this.tone({ freq: 220, endFreq: 460, dur: 0.12, type: "sine", gain: 0.07 });
  }

  hit() {
    this.noise({ dur: 0.12, gain: 0.12, filter: 800, sweepTo: 200 });
    this.tone({ freq: 150, endFreq: 70, dur: 0.16, type: "square", gain: 0.08 });
  }

  reaction() {
    this.resume();
    this.noise({ dur: 0.16, gain: 0.2, filter: 4200, sweepTo: 700, type: "highpass" });
    this.tone({ freq: 300, endFreq: 900, dur: 0.18, type: "square", gain: 0.1 });
    this.tone({ freq: 900, endFreq: 500, dur: 0.22, type: "triangle", gain: 0.1, delay: 0.05 });
  }

  death() {
    this.resume();
    this.tone({ freq: 400, endFreq: 90, dur: 0.5, type: "sawtooth", gain: 0.12 });
    this.tone({ freq: 200, endFreq: 50, dur: 0.7, type: "triangle", gain: 0.1, delay: 0.06 });
    this.noise({ dur: 0.4, gain: 0.1, filter: 500, sweepTo: 100 });
  }

  crate() {
    this.resume();
    this.tone({ freq: 660, endFreq: 990, dur: 0.1, type: "triangle", gain: 0.1 });
    this.tone({ freq: 990, endFreq: 1320, dur: 0.12, type: "sine", gain: 0.08, delay: 0.08 });
  }

  turn() {
    this.tone({ freq: 520, endFreq: 660, dur: 0.09, type: "triangle", gain: 0.06 });
    this.tone({ freq: 780, endFreq: 780, dur: 0.07, type: "sine", gain: 0.04, delay: 0.08 });
  }

  win() {
    this.resume();
    const notes = [523.25, 659.25, 783.99, 1046.5, 1318.5];
    notes.forEach((f, i) => {
      this.tone({ freq: f, dur: 0.3, type: "triangle", gain: 0.12, delay: i * 0.11 });
      this.tone({ freq: f / 2, dur: 0.34, type: "sine", gain: 0.06, delay: i * 0.11 });
    });
    this.tone({ freq: 1046.5, dur: 0.8, type: "sine", gain: 0.07, delay: 0.55 });
  }
}

import { simulateShot, WEAPONS } from "./physics.js";

const DIFF = {
  easy: { noise: 68, angleJitter: 0.06, powerJitter: 0.07, samples: 55 },
  normal: { noise: 26, angleJitter: 0.022, powerJitter: 0.025, samples: 85 },
  hard: { noise: 9, angleJitter: 0.007, powerJitter: 0.008, samples: 110 },
};

function dist(ax, ay, bx, by) {
  return Math.hypot(ax - bx, ay - by);
}

/**
 * Pick a ballistic shot for the CPU. Scores every sampled arc by how close its
 * impact lands to an enemy worm, then adds a difficulty-scaled human error.
 */
export function chooseShot({ worm, enemies, wind, terrain, structures, worms, difficulty = "normal" }) {
  const cfg = DIFF[difficulty] || DIFF.normal;
  if (!enemies.length) return null;

  let target = enemies[0];
  let bestD = Infinity;
  for (const e of enemies) {
    const d = dist(worm.x, worm.y, e.x, e.y);
    if (d < bestD) { bestD = d; target = e; }
  }

  const dir = target.x >= worm.x ? 1 : -1;
  const useGrenade = worm.ammo.grenade > 0 && Math.random() < 0.22;
  const weapon = useGrenade ? "grenade" : "bazooka";
  const elevations = [-12, -2, 8, 18, 28, 38, 47, 56, 65, 73, 79];
  const powers = [0.34, 0.42, 0.5, 0.58, 0.66, 0.74, 0.82, 0.9, 0.97];

  let best = null;
  let checked = 0;
  for (const elev of elevations) {
    for (const power of powers) {
      if (checked++ > cfg.samples) break;
      const rad = (elev * Math.PI) / 180;
      const angle = dir > 0 ? rad : Math.PI - rad;
      const mx = worm.x + Math.cos(angle) * 26;
      const my = worm.y - 6 + Math.sin(angle) * 26;
      const sim = simulateShot({
        x: mx, y: my, angle, power, weapon, wind, terrain, structures, worms,
        ignoreWormId: worm.id, maxTime: 6.5,
      });
      if (!sim) continue;

      let score;
      if (sim.hitWorm) {
        score = sim.hitWorm.team === worm.team ? 3000 : -40;
      } else {
        let nearest = Infinity;
        for (const e of enemies) {
          nearest = Math.min(nearest, dist(sim.impact.x, sim.impact.y, e.x, e.y));
        }
        score = nearest;
        if (sim.impact.type === "miss" || sim.impact.type === "timeout") score += 700;
      }

      // Don't blow yourself up.
      const selfD = dist(sim.impact.x, sim.impact.y, worm.x, worm.y);
      if (selfD < 95) score += (95 - selfD) * 6;
      for (const w of worms) {
        if (w.team === worm.team && w.id !== worm.id) {
          const d = dist(sim.impact.x, sim.impact.y, w.x, w.y);
          if (d < 80) score += (80 - d) * 4;
        }
      }

      score += Math.random() * cfg.noise;
      if (!best || score < best.score) {
        best = { angle, power, weapon, score, impact: sim.impact, sim };
      }
    }
  }

  if (!best) {
    return { angle: dir > 0 ? -0.7 : Math.PI + 0.7, power: 0.7, weapon: "bazooka" };
  }

  // A little sloppiness on lower difficulties.
  const angle = best.angle + (Math.random() * 2 - 1) * cfg.angleJitter;
  const power = Math.max(0.12, Math.min(1, best.power + (Math.random() * 2 - 1) * cfg.powerJitter));
  return { angle, power, weapon: best.weapon, predicted: best.impact };
}

export function weaponName(id) {
  return WEAPONS[id]?.label || id;
}

import { WORLD_W, WORLD_H } from "./terrain.js";
import { WEAPONS } from "./physics.js";

const MATS = {
  wood: { base: "#b9793f", light: "#e0a666", dark: "#7c4a22", edge: "#5a3316", line: "#8e5a2c" },
  brick: { base: "#b95747", light: "#e58a72", dark: "#7d3329", edge: "#5a211a", line: "#e3b39f" },
  metal: { base: "#8298ad", light: "#c3d4e3", dark: "#52667a", edge: "#334454", line: "#dbe8f3" },
};

function rr(ctx, x, y, w, h, r) {
  const rad = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rad, y);
  ctx.arcTo(x + w, y, x + w, y + h, rad);
  ctx.arcTo(x + w, y + h, x, y + h, rad);
  ctx.arcTo(x, y + h, x, y, rad);
  ctx.arcTo(x, y, x + w, y, rad);
  ctx.closePath();
}

function hash(n) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

export class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d");
    this.cw = 0;
    this.ch = 0;
    this.dpr = 1;
    this.shakeX = 0;
    this.shakeY = 0;
    this.clouds = [];
    for (let i = 0; i < 8; i++) {
      this.clouds.push({
        x: hash(i * 3.1) * 1700,
        y: 0.04 + hash(i * 7.7) * 0.26,
        s: 0.55 + hash(i * 2.3) * 0.8,
        speed: 4 + hash(i * 5.9) * 9,
        alpha: 0.32 + hash(i * 9.2) * 0.4,
      });
    }
    this.resize();
  }

  resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = this.canvas.clientWidth || window.innerWidth;
    const h = this.canvas.clientHeight || window.innerHeight;
    this.cw = w;
    this.ch = h;
    this.dpr = dpr;
    this.canvas.width = Math.max(1, Math.round(w * dpr));
    this.canvas.height = Math.max(1, Math.round(h * dpr));
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.ctx.imageSmoothingEnabled = true;
    this.ctx.imageSmoothingQuality = "high";
  }

  toScreenX(wx, state) {
    return this.cw / 2 + (wx - state.cam.x) * state.cam.scale + this.shakeX;
  }

  toScreenY(wy, state) {
    return this.ch / 2 + (wy - state.cam.y) * state.cam.scale + this.shakeY;
  }

  draw(state) {
    const ctx = this.ctx;
    const { cw, ch } = this;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, cw, ch);

    this.shakeX = Math.sin(state.time * 93) * state.shake;
    this.shakeY = Math.cos(state.time * 77) * state.shake * 0.65;

    this.drawBackground(state);

    ctx.save();
    ctx.translate(cw / 2 + this.shakeX, ch / 2 + this.shakeY);
    ctx.scale(state.cam.scale, state.cam.scale);
    ctx.translate(-state.cam.x, -state.cam.y);

    this.drawWorld(state);

    ctx.restore();

    this.drawScreenFx(state);
  }

  drawBackground(state) {
    const ctx = this.ctx;
    const { cw, ch } = this;
    const sky = ctx.createLinearGradient(0, 0, 0, ch);
    sky.addColorStop(0, "#5fb7ef");
    sky.addColorStop(0.42, "#9ad8f8");
    sky.addColorStop(0.75, "#d9f2fb");
    sky.addColorStop(1, "#f0e4c8");
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, cw, ch);

    const parX = (state.cam.x - WORLD_W / 2) * 0.16;
    const parY = (state.cam.y - WORLD_H / 2) * 0.08;

    // Sun
    const sunX = cw * 0.79 - parX * 0.4;
    const sunY = ch * 0.17 - parY;
    const glow = ctx.createRadialGradient(sunX, sunY, 8, sunX, sunY, Math.max(110, cw * 0.13));
    glow.addColorStop(0, "rgba(255, 244, 196, 0.9)");
    glow.addColorStop(0.35, "rgba(255, 229, 150, 0.28)");
    glow.addColorStop(1, "rgba(255, 220, 140, 0)");
    ctx.fillStyle = glow;
    ctx.fillRect(sunX - cw * 0.2, sunY - cw * 0.2, cw * 0.4, cw * 0.4);
    ctx.fillStyle = "#fff6cf";
    ctx.beginPath();
    ctx.arc(sunX, sunY, Math.max(22, cw * 0.023), 0, Math.PI * 2);
    ctx.fill();

    // Clouds
    for (const c of this.clouds) {
      const span = cw + 420;
      let x = ((c.x - state.time * c.speed - parX * 0.7) % span + span) % span - 210;
      const y = ch * c.y - parY * 0.7;
      const s = c.s * Math.max(0.7, cw / 1200);
      ctx.globalAlpha = c.alpha;
      ctx.fillStyle = "#ffffff";
      ctx.beginPath();
      ctx.ellipse(x, y, 46 * s, 15 * s, 0, 0, Math.PI * 2);
      ctx.ellipse(x - 30 * s, y + 4 * s, 26 * s, 11 * s, 0, 0, Math.PI * 2);
      ctx.ellipse(x + 34 * s, y + 5 * s, 30 * s, 12 * s, 0, 0, Math.PI * 2);
      ctx.ellipse(x + 6 * s, y - 10 * s, 26 * s, 15 * s, 0, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // Birds
    ctx.strokeStyle = "rgba(35, 62, 82, 0.4)";
    ctx.lineWidth = 1.4;
    for (let i = 0; i < 3; i++) {
      const bx = ((state.time * (11 + i * 4) + i * 260) % (cw + 200)) - 100;
      const by = ch * 0.2 + i * 26 + Math.sin(state.time * 0.7 + i) * 6;
      const flap = Math.sin(state.time * 4 + i * 2) * 3;
      ctx.beginPath();
      ctx.moveTo(bx - 6, by + flap);
      ctx.quadraticCurveTo(bx - 2, by - 2, bx, by);
      ctx.quadraticCurveTo(bx + 2, by - 2, bx + 6, by + flap);
      ctx.stroke();
    }

    // Wind streaks
    const wind = state.wind || 0;
    if (Math.abs(wind) > 18) {
      ctx.strokeStyle = `rgba(255,255,255,${0.05 + Math.min(0.1, Math.abs(wind) / 900)})`;
      ctx.lineWidth = 1.2;
      for (let i = 0; i < 9; i++) {
        const sx = ((state.time * (40 + Math.abs(wind) * 1.6) * Math.sign(wind) + i * 190) % (cw + 300) + cw + 300) % (cw + 300) - 150;
        const sy = ch * 0.1 + hash(i * 4.7) * ch * 0.42;
        ctx.beginPath();
        ctx.moveTo(sx, sy);
        ctx.lineTo(sx + Math.sign(wind) * (24 + hash(i) * 34), sy - 3);
        ctx.stroke();
      }
    }

    // Distant hills
    const horizon = this.toScreenY(492, state);
    this.drawHills(state, horizon + 24, "#a8d6b4", 0.55, 0.55, 92);
    this.drawHills(state, horizon + 54, "#7cb998", 0.72, 0.85, 66);

    // Underground extension when the camera shows past the world floor
    const floorY = this.toScreenY(WORLD_H, state);
    if (floorY < ch) {
      const g = ctx.createLinearGradient(0, floorY, 0, ch);
      g.addColorStop(0, "#4a3123");
      g.addColorStop(0.35, "#332218");
      g.addColorStop(1, "#1c120d");
      ctx.fillStyle = g;
      ctx.fillRect(0, floorY, cw, ch - floorY);
      ctx.fillStyle = "rgba(0,0,0,0.18)";
      for (let i = 0; i < 40; i++) {
        const x = hash(i * 3.3) * cw;
        const y = floorY + hash(i * 9.1) * (ch - floorY);
        ctx.beginPath();
        ctx.arc(x, y, 1 + hash(i) * 2.4, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }

  drawHills(state, baseY, color, alpha, parallax, amp) {
    const ctx = this.ctx;
    const { cw } = this;
    const offset = (state.cam.x - WORLD_W / 2) * parallax;
    ctx.globalAlpha = alpha;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(-40, baseY + 200);
    for (let x = -40; x <= cw + 40; x += 16) {
      const wx = x + offset;
      const y = baseY - Math.sin(wx * 0.0042 + 1.2) * amp * 0.45 - Math.sin(wx * 0.011 + 0.4) * amp * 0.22;
      ctx.lineTo(x, y);
    }
    ctx.lineTo(cw + 40, baseY + 200);
    ctx.closePath();
    ctx.fill();
    ctx.globalAlpha = 1;
  }

  drawWorld(state) {
    const ctx = this.ctx;
    const terrain = state.terrain;

    terrain.draw(ctx);

    // tombstone markers
    for (const w of state.worms) {
      if (!w.alive) this.drawGrave(ctx, w);
    }

    terrain.drawTufts(ctx, state.time);

    // structures & crates
    for (const s of state.structures) this.drawStructure(ctx, s, state);

    // aim preview behind the worm
    if (state.phase === "input" && !state.buildMode && state.active && state.active.alive && state.scene === "play") {
      this.drawAim(ctx, state);
    }

    // projectiles
    for (const p of state.projectiles) this.drawProjectile(ctx, p, state);

    // worms
    for (const w of state.worms) if (w.alive) this.drawWorm(ctx, w, state);

    // particles
    this.drawParticles(ctx, state);

    // floating texts
    this.drawFloaters(ctx, state);

    // build ghost
    if (state.buildMode && state.ghost) this.drawBuildGhost(ctx, state);

    // damage flash tint
    if (state.hitFlash > 0) {
      ctx.fillStyle = `rgba(255,255,255,${state.hitFlash * 0.12})`;
      ctx.fillRect(state.cam.x - 2000, state.cam.y - 2000, 4000, 4000);
    }
  }

  /* ---------------- structures ---------------- */
  drawStructure(ctx, s, state) {
    if (s.type === "crate") { this.drawCrate(ctx, s, state); return; }
    const c = MATS[s.mat] || MATS.wood;
    const t = Math.min(1, (state.time - s.born) * 8);
    const pop = 0.75 + 0.25 * (1 - Math.pow(1 - t, 3));
    const cx = s.cellX + 22;
    const cy = s.cellY + 22;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(pop, pop);
    ctx.translate(-cx, -cy);

    if (s.type === "wall") {
      const x = s.cellX + 3, y = s.cellY + 3, w = 38, h = 38;
      const g = ctx.createLinearGradient(x, y, x + w, y + h);
      g.addColorStop(0, c.light);
      g.addColorStop(0.55, c.base);
      g.addColorStop(1, c.dark);
      ctx.fillStyle = g;
      rr(ctx, x, y, w, h, 3);
      ctx.fill();
      ctx.strokeStyle = c.edge;
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.save();
      rr(ctx, x + 2, y + 2, w - 4, h - 4, 2);
      ctx.clip();
      if (s.mat === "wood") {
        ctx.strokeStyle = "rgba(90,51,22,0.6)";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(x + 4, y + 4); ctx.lineTo(x + w - 4, y + h - 4);
        ctx.moveTo(x + w - 4, y + 4); ctx.lineTo(x + 4, y + h - 4);
        ctx.stroke();
        ctx.strokeStyle = "rgba(255,220,170,0.22)";
        ctx.lineWidth = 1;
        for (let i = 1; i < 4; i++) {
          ctx.beginPath();
          ctx.moveTo(x + 4, y + i * 10 + 2);
          ctx.lineTo(x + w - 4, y + i * 10 + 2);
          ctx.stroke();
        }
      } else if (s.mat === "brick") {
        ctx.strokeStyle = "rgba(255,220,200,0.32)";
        ctx.lineWidth = 1.4;
        for (let row = 0; row < 4; row++) {
          const yy = y + 4 + row * 8;
          ctx.beginPath(); ctx.moveTo(x + 2, yy); ctx.lineTo(x + w - 2, yy); ctx.stroke();
          const off = row % 2 ? 9 : 0;
          for (let col = 0; col < 3; col++) {
            const xx = x + 6 + off + col * 15;
            if (xx < x + w - 3) { ctx.beginPath(); ctx.moveTo(xx, yy); ctx.lineTo(xx, yy + 8); ctx.stroke(); }
          }
        }
      } else {
        ctx.strokeStyle = "rgba(255,255,255,0.2)";
        ctx.lineWidth = 1;
        for (let i = 0; i < 4; i++) {
          ctx.beginPath(); ctx.moveTo(x + 3, y + 7 + i * 8); ctx.lineTo(x + w - 3, y + 7 + i * 8); ctx.stroke();
        }
        ctx.fillStyle = "rgba(255,255,255,0.55)";
        for (const [nx, ny] of [[7, 7], [w - 7, 7], [7, h - 7], [w - 7, h - 7]]) {
          ctx.beginPath(); ctx.arc(x + nx, y + ny, 1.5, 0, Math.PI * 2); ctx.fill();
        }
      }
      ctx.restore();

      // top highlight
      ctx.fillStyle = "rgba(255,255,255,0.18)";
      ctx.fillRect(x + 4, y + 3, w - 8, 2);
    } else if (s.type === "floor") {
      const x = s.cellX + 1, y = s.cellY + 17, w = 42, h = 11;
      ctx.fillStyle = c.edge;
      rr(ctx, x - 1, y - 1, w + 2, h + 2, 3);
      ctx.fill();
      const g = ctx.createLinearGradient(0, y, 0, y + h);
      g.addColorStop(0, c.light);
      g.addColorStop(0.4, c.base);
      g.addColorStop(1, c.dark);
      ctx.fillStyle = g;
      rr(ctx, x, y, w, h, 2);
      ctx.fill();
      ctx.strokeStyle = "rgba(0,0,0,0.22)";
      ctx.lineWidth = 1;
      for (let i = 1; i < 4; i++) {
        ctx.beginPath(); ctx.moveTo(x + i * 10.5, y + 1); ctx.lineTo(x + i * 10.5, y + h - 1); ctx.stroke();
      }
      // supports
      ctx.strokeStyle = c.edge;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(x + 6, y + h); ctx.lineTo(x + 12, y + 22);
      ctx.moveTo(x + w - 6, y + h); ctx.lineTo(x + w - 12, y + 22);
      ctx.stroke();
      ctx.fillStyle = "rgba(255,255,255,0.16)";
      ctx.fillRect(x + 2, y + 1, w - 4, 1.5);
    } else if (s.type === "ramp") {
      const x = s.cellX, y = s.cellY;
      ctx.beginPath();
      if (s.dir >= 0) {
        ctx.moveTo(x, y + 44);
        ctx.lineTo(x + 44, y + 44);
        ctx.lineTo(x + 44, y);
      } else {
        ctx.moveTo(x, y + 44);
        ctx.lineTo(x + 44, y + 44);
        ctx.lineTo(x, y);
      }
      ctx.closePath();
      const g = ctx.createLinearGradient(x, y + 44, x + 44, y);
      g.addColorStop(0, c.dark);
      g.addColorStop(0.5, c.base);
      g.addColorStop(1, c.light);
      ctx.fillStyle = g;
      ctx.fill();
      ctx.strokeStyle = c.edge;
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.save();
      ctx.clip();
      ctx.strokeStyle = s.mat === "metal" ? "rgba(255,255,255,0.28)" : "rgba(0,0,0,0.25)";
      ctx.lineWidth = 1.6;
      for (let i = 1; i < 6; i++) {
        ctx.beginPath();
        if (s.dir >= 0) { ctx.moveTo(x, y + 44 - i * 7); ctx.lineTo(x + 44, y + 44 - i * 7 - 44 + 2); }
        else { ctx.moveTo(x + 44, y + 44 - i * 7); ctx.lineTo(x, y + 44 - i * 7 - 44 + 2); }
        ctx.stroke();
      }
      ctx.restore();
      ctx.strokeStyle = "rgba(255,255,255,0.28)";
      ctx.lineWidth = 2;
      ctx.beginPath();
      if (s.dir >= 0) { ctx.moveTo(x + 1, y + 43); ctx.lineTo(x + 43, y + 1); }
      else { ctx.moveTo(x + 43, y + 43); ctx.lineTo(x + 1, y + 1); }
      ctx.stroke();
    }

    // team accent
    ctx.fillStyle = s.team === 0 ? "rgba(69,182,255,0.7)" : "rgba(255,93,108,0.7)";
    if (s.type === "wall") ctx.fillRect(s.cellX + 6, s.cellY + 39, 32, 2);
    else if (s.type === "floor") ctx.fillRect(s.cellX + 4, s.cellY + 26, 36, 2);

    if (s.flash > 0) {
      ctx.fillStyle = `rgba(255,255,255,${Math.min(0.8, s.flash)})`;
      if (s.type === "wall") ctx.fillRect(s.cellX + 3, s.cellY + 3, 38, 38);
      else if (s.type === "floor") ctx.fillRect(s.cellX + 1, s.cellY + 17, 42, 11);
      else { ctx.beginPath(); ctx.moveTo(s.cellX, s.cellY + 44); ctx.lineTo(s.cellX + 44, s.cellY + 44); ctx.lineTo(s.dir >= 0 ? s.cellX + 44 : s.cellX, s.cellY); ctx.closePath(); ctx.fill(); }
    }
    ctx.restore();

    if (s.hp < s.maxHp) this.drawHpBar(ctx, s.cellX + 7, s.cellY - 7, 30, s.hp / s.maxHp, s.team);
  }

  drawCrate(ctx, s, state) {
    const r = s.rects[0];
    const pulse = 0.5 + 0.5 * Math.sin(state.time * 3.4 + r.x);
    const cx = r.x + r.w / 2, cy = r.y + r.h / 2;
    ctx.save();
    const glow = ctx.createRadialGradient(cx, cy, 4, cx, cy, 40);
    glow.addColorStop(0, `rgba(255,220,90,${0.18 + pulse * 0.18})`);
    glow.addColorStop(1, "rgba(255,220,90,0)");
    ctx.fillStyle = glow;
    ctx.beginPath(); ctx.arc(cx, cy, 40, 0, Math.PI * 2); ctx.fill();

    ctx.fillStyle = "#7c4a22";
    rr(ctx, r.x - 1, r.y - 1, r.w + 2, r.h + 2, 4);
    ctx.fill();
    const g = ctx.createLinearGradient(r.x, r.y, r.x, r.y + r.h);
    g.addColorStop(0, "#e3a961");
    g.addColorStop(1, "#a86a31");
    ctx.fillStyle = g;
    rr(ctx, r.x, r.y, r.w, r.h, 3);
    ctx.fill();
    ctx.strokeStyle = "#5a3316";
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.strokeStyle = "rgba(255,240,190,0.5)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(r.x + 3, r.y + r.h - 4); ctx.lineTo(r.x + r.w - 3, r.y + 4);
    ctx.stroke();
    ctx.fillStyle = "#5a3316";
    ctx.fillRect(r.x + 4, r.y + r.h * 0.32, r.w - 8, 3);
    ctx.fillRect(r.x + 4, r.y + r.h * 0.66, r.w - 8, 3);
    ctx.fillStyle = `rgba(255,230,120,${0.7 + pulse * 0.3})`;
    ctx.font = "900 16px Bungee, Arial Black, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("?", cx, cy + 1);
    ctx.restore();
    if (s.hp < s.maxHp) this.drawHpBar(ctx, r.x + 2, r.y - 7, r.w - 4, s.hp / s.maxHp, -1);
  }

  drawHpBar(ctx, x, y, w, ratio, team) {
    ctx.fillStyle = "rgba(8,14,24,0.75)";
    rr(ctx, x - 1, y - 1, w + 2, 6, 3);
    ctx.fill();
    ctx.fillStyle = ratio > 0.55 ? "#65d98b" : ratio > 0.28 ? "#ffd447" : "#ff5d6c";
    rr(ctx, x, y, Math.max(2, w * Math.max(0, ratio)), 4, 2);
    ctx.fill();
  }

  drawGrave(ctx, w) {
    const x = w.deathX ?? w.x;
    const y = (w.deathY ?? w.y) + 8;
    ctx.save();
    ctx.globalAlpha = 0.75;
    ctx.fillStyle = "#6f7c8a";
    rr(ctx, x - 7, y - 18, 14, 20, 6);
    ctx.fill();
    ctx.fillStyle = "#4b5662";
    ctx.fillRect(x - 7, y - 4, 14, 3);
    ctx.fillStyle = "rgba(30,40,50,0.55)";
    ctx.font = "900 8px Nunito, sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("RIP", x, y - 8);
    ctx.restore();
  }
}

