+    // cheeks + mouth
+    ctx.fillStyle = "rgba(255, 120, 150, 0.4)";
+    ctx.beginPath(); ctx.arc(-6.2, -6.5, 2, 0, Math.PI * 2); ctx.fill();
+    ctx.beginPath(); ctx.arc(6.2, -6.5, 2, 0, Math.PI * 2); ctx.fill();
+    ctx.strokeStyle = "#8d3c52";
+    ctx.lineWidth = 1;
