  worm.fallDist = 0;

  for (let i = 0; i < 8; i++) {
    addParticle({
      kind: "spark", x: mx, y: my,
      vx: Math.cos(angle) * rand(60, 240) + rand(-50, 50),
      vy: Math.sin(angle) * rand(60, 240) + rand(-50, 50),
      life: rand(0.15, 0.35), maxLife: 0.35, size: rand(1.5, 2.8),
      color: i % 2 ? "#ffd447" : "#ff9b3d",
